<?php use App\Support\App;App::requireAdmin();$rows=App::db()->query('SELECT o.*,p.name product_name FROM orders o JOIN products p ON p.id=o.product_id ORDER BY o.id DESC LIMIT 200')->fetchAll();$title='Admin Orders';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex flex-col sm:flex-row sm:items-end justify-between gap-4"><div><h1 class="page-title">Orders</h1><p class="page-sub">Review dan ubah status beberapa order sekaligus.</p></div><div class="flex gap-2"><select id="status" class="field !w-auto"><option value="processing">Processing</option><option value="success">Done</option><option value="rejected">Failed + Refund</option></select><button class="btn btn-dark" onclick="applyBulk()">Apply</button></div></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[680px]"><thead><tr><th></th><th>Order</th><th>IMEI</th><th>Service</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td><input class="oid" type="checkbox" value="<?=$r['id']?>"></td><td class="font-semibold"><?=htmlspecialchars($r['order_number'])?></td><td class="font-mono"><?=htmlspecialchars($r['imei'])?></td><td><?=htmlspecialchars($r['product_name'])?></td><td><span class="badge"><?=htmlspecialchars($r['status'])?></span></td></tr><?php endforeach?></tbody></table></div><script>async function applyBulk(){let ids=[...document.querySelectorAll('.oid:checked')].map(x=>+x.value);if(!ids.length)return Swal.fire('Select orders','Pilih minimal satu order.','info');let r=await fetch('/api/admin/orders/bulk',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify({ids,status:status.value})}),j=await r.json();Swal.fire(j.ok?'Updated':'Perlu dicek',j.message||'Order updated',j.ok?'success':'warning').then(()=>location.reload())}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>